mapper.select:
SELECT 
FROM bom_version v JOIN bom b ON b.bom_id = v.bom_id JOIN item i ON i.item_id = b.product_item_id
WHERE v.bom_version_id = #{versionId}

SELECT item_id, item_code, item_name, item_kind, unit_code, is_active FROM item
WHERE is_active = 1 AND item_kind = #{kind}
AND unit_code = #{unit}
ORDER BY item_code
